413→   413→			logger.debug("exception >>> {}", ignore);
414→   414→			logger.error("Exception Catched !!! >>>> \n" + ignore.getMessage());
415→   415→		} finally {
416→   416→			writer.endObject();
417→   417→			writer.key("success").value(true);
418→   418→		}
